def _parse() -> list[dict]:
    out, topic = [], ""
    for line in RAW.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        if line.startswith("# "):
            topic = line[2:]
            continue
        w, ipa, pos, def_en, def_vi, vi, ex_en, ex_vi, level, emoji = line.split("|")
        out.append({"word": w, "ipa": ipa, "pos": pos, "def_en": def_en, "def_vi": def_vi, "vi": vi,
                    "ex_en": ex_en, "ex_vi": ex_vi, "level": level, "topic": topic, "emoji": emoji})
    return out


MORE = _parse()
